/* Ruby is presentation only: never add readings to source text or offsets. */
window.HarukaStudyText = {
  plain(node) {
    const copy = node.cloneNode(true);
    copy.querySelectorAll?.('rt,rp').forEach((el) => el.remove());
    return copy.textContent;
  },
  walker(node) {
    return document.createTreeWalker(node, NodeFilter.SHOW_TEXT, {
      acceptNode: (text) =>
        text.parentElement?.closest('rt,rp')
          ? NodeFilter.FILTER_REJECT
          : NodeFilter.FILTER_ACCEPT,
    });
  },
};
